3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Rejects a create when the owner's city already contains 50 or more owners, before
10	 * {@link SaveOwner} runs. Handled with 409 by {@code CityAtCapacityHandler}.
11	 */
12	public class CheckCityCapacity {
13	
14	    static final int CAPACITY = 50;
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
17	            throws CityAtCapacityException {
18	        String city = normalize(owner.getCity());
19	        long count = ownerRepository.findAll().stream()
20	                .filter(other -> !other.getId().equals(owner.getId()))
21	                .filter(other -> city.equals(normalize(other.getCity())))
22	                .count();
23	        if (count >= CAPACITY) {
24	            throw new CityAtCapacityException(owner.getCity());
25	        }
26	    }
27	
28	    static String normalize(String value) {
29	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
30	    }
31	}
