3	/**
4	 * Thrown when creating an owner whose city already contains 50 or more owners.
5	 * Handled by {@link CityAtCapacityHandler}, which responds 409.
6	 */
7	public class CityAtCapacityException extends Exception {
8	
9	    public CityAtCapacityException(String city) {
10	        super("City already at capacity: " + city);
11	    }
12	}
