18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    @Autowired
25	    protected OwnerRepository ownerRepository;
26	
27	    /** Membership points for the owner (see {@link MembershipLevel}). */
28	    protected int membershipPoints(Owner owner) {
29	        return MembershipLevel.points(owner, ownerRepository);
30	    }
31	
32	    /** Membership level derived from the owner's membership points. */
33	    protected int membershipLevel(Owner owner) {
34	        return org.springframework.samples.petclinic.rest.function.owner.HouseholdCeiling.cap(
35	            MembershipLevel.level(membershipPoints(owner)), owner, ownerRepository);
36	    }
37	
38	    @Mapping(target = "selfLink", expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
39	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
40	    @Mapping(target = "salutation", expression = "java(owner.getTitle() == null ? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
41	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
42	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() != null && owner.getRegistrationDate() != null ? owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", org.springframework.samples.petclinic.rest.function.owner.FiscalYear.endYear(owner.getRegistrationDate()) % 100) : null)")
43	    @Mapping(target = "fiscalYear", expression = "java(owner.getRegistrationDate() == null ? null : org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(owner.getRegistrationDate()))")
44	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
45	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
46	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.rest.function.owner.Locality.locality(owner))")
47	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.rest.function.owner.Timezone.of(org.springframework.samples.petclinic.rest.function.owner.Locality.locality(owner)))")
48	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"EMAIL\" : \"PHONE\")")
49	    @Mapping(target = "ageBand", expression = "java(owner.getBirthDate() == null ? null : org.springframework.samples.petclinic.rest.function.owner.AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
50	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckUniqueIdentity.identityKey(owner))")
51	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.rest.function.owner.CheckDigit.checkDigit(owner))")
52	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneDisplay.display(owner.getTelephone()))")
53	    public abstract OwnerDto toOwnerDto(Owner owner);
54	
55	    public abstract Owner toOwner(OwnerDto ownerDto);
56	
57	    @Mapping(target = "id", ignore = true)
58	    @Mapping(target = "pets", ignore = true)
59	    @Mapping(target = "registrationDate", expression = "java(ownerDto.getRegistrationDate() != null ? ownerDto.getRegistrationDate() : java.time.LocalDate.now())")
60	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
61	
62	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
63	
64	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
65	
66	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
67	        OwnerPageDto ownerPageDto = new OwnerPageDto();
68	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
69	        ownerPageDto.setPage(ownerPage.getNumber());
70	        ownerPageDto.setSize(ownerPage.getSize());
71	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
72	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
73	        return ownerPageDto;
74	    }
75	}
